-- Onboarding imobiliário v2 (pedido do dono 2026-10-16): diagnóstico curto
-- antes do cadastro e 5 etapas depois, com respostas "Não sei" / "Não se
-- aplica" / "Preencher depois". Ver docs/DECISIONS.md (2026-10-16).
--
-- 1) companies.answer_status: estado de cada resposta da ficha, separado do
--    valor ({"faixa_preco":"unknown","creci":"later",...}). playbook_answers
--    continua só com valores reais — as 6 functions que já leem
--    playbook_answers seguem funcionando sem mudança.
--    Estados: unknown = "Não sei"; na = "Não se aplica"; later = "Preencher
--    depois"; auto = veio de integração (ex.: Instagram) e falta confirmar.
--    Sem estado + com valor = preenchido pelo dono.
alter table public.companies add column if not exists answer_status jsonb not null default '{}'::jsonb;

-- 2) Ficha imoveis_rio: perguntas novas em config.onboarding_v2 (etapas,
--    perfis, condicionais, "por que perguntamos", ações por prioridade,
--    hipóteses de público e checagens do diagnóstico). Tudo de setor na ficha
--    (regra 6). config.onboarding_questions (as 6 antigas) NÃO muda: é o que
--    o servidor (setupReady) ainda confere. 5 delas estão no v2 com as mesmas
--    chaves e opções; a 6ª (transacao) é calculada de "servicos" (derive).
update public.vertical_playbooks
set config = config || jsonb_build_object('onboarding_v2', $v2${
 "steps": [
  {"key": "operacao", "title": {"pt": "Sua operação imobiliária", "en": "Your real estate operation"}, "subtitle": {"pt": "Como o seu negócio funciona hoje — pra o Sales Boost falar a língua da sua operação."}},
  {"key": "mercado", "title": {"pt": "Seus imóveis e seu mercado", "en": "Your properties and market"}, "subtitle": {"pt": "O tipo de imóvel e de cliente muda tudo: o tom, o formato e onde vale aparecer."}},
  {"key": "prioridade", "title": {"pt": "Sua prioridade comercial", "en": "Your commercial priority"}, "subtitle": {"pt": "Gerar demanda já é o trabalho do Sales Boost. Aqui você diz onde quer melhorar primeiro."}},
  {"key": "canais", "title": {"pt": "Seus canais e desempenho", "en": "Your channels and performance"}, "subtitle": {"pt": "Como a atenção chega e vira conversa hoje. Não sabe algum número? Tudo bem — marque \"Não sei\"."}},
  {"key": "inteligencia", "title": {"pt": "Sua inteligência comercial", "en": "Your commercial intelligence"}, "subtitle": {"pt": "O que entendemos do seu negócio — separando o que você contou, o que lemos e o que ainda é hipótese."}}
 ],
 "questions": [
  {"key": "perfil", "step": "operacao", "type": "select", "label": {"pt": "Qual é o seu papel?"}, "why": {"pt": "Uma imobiliária e um corretor autônomo precisam de perguntas (e estratégias) diferentes."}, "options": [{"pt": "Sou dono(a) ou sócio(a) da imobiliária", "key": "imobiliaria_dono", "business_types": ["Imobiliária"], "org": true}, {"pt": "Sou gestor(a) ou coordenador(a) comercial", "key": "gestor", "business_types": ["Imobiliária"], "org": true}, {"pt": "Sou corretor(a) autônomo(a)", "key": "corretor_autonomo", "business_types": ["Corretor(a) de imóveis"]}, {"pt": "Sou corretor(a) associado(a) a uma imobiliária", "key": "corretor_associado", "business_types": ["Corretor(a) de imóveis"]}], "allow": [], "diagnostic": true},
  {"key": "imobiliaria_parceira", "step": "operacao", "type": "text", "label": {"pt": "Com qual imobiliária você trabalha?"}, "why": {"pt": "Por enquanto só anotamos. Em breve a imobiliária vai poder convidar a equipe dela pro Sales Boost."}, "profiles": ["corretor_associado"], "allow": ["unknown", "later"]},
  {"key": "servicos", "step": "operacao", "type": "multi_select", "label": {"pt": "O que você faz hoje?"}, "why": {"pt": "Venda, locação e lançamento pedem conteúdos e chamadas diferentes."}, "options": [{"pt": "Venda"}, {"pt": "Locação"}, {"pt": "Lançamentos"}, {"pt": "Administração de imóveis"}, {"pt": "Aluguel por temporada"}], "allow": ["later"], "diagnostic": true},
  {"key": "bairros", "step": "operacao", "type": "multi_text", "label": {"pt": "Bairros e regiões onde você mais atua"}, "why": {"pt": "É com eles que o Sales Boost busca concorrentes, tendências e escreve sobre a vizinhança."}, "max": 5, "allow": ["later"], "diagnostic": true, "placeholder": {"pt": "Ex.: Copacabana, Botafogo, Barra"}},
  {"key": "modelo_carteira", "step": "operacao", "type": "select", "label": {"pt": "De quem são os imóveis que vocês comercializam?"}, "why": {"pt": "Ajuda a decidir se o foco é captar imóveis ou vender o que já está na carteira."}, "profiles": ["imobiliaria_dono", "gestor"], "options": [{"pt": "De terceiros (proprietários)"}, {"pt": "Próprios"}, {"pt": "Os dois"}], "allow": ["unknown", "later"]},
  {"key": "total_corretores", "step": "operacao", "type": "select", "label": {"pt": "Quantos corretores a imobiliária tem no total?"}, "why": {"pt": "Dimensiona o volume de conteúdo e quantos perfis podem ser trabalhados."}, "profiles": ["imobiliaria_dono", "gestor"], "options": [{"pt": "1 a 5"}, {"pt": "6 a 15"}, {"pt": "16 a 50"}, {"pt": "Mais de 50"}], "allow": ["unknown", "later"]},
  {"key": "corretores_plataforma", "step": "operacao", "type": "select", "label": {"pt": "Quantos vão usar o Sales Boost no começo?"}, "why": {"pt": "É diferente do total da equipe — dá pra começar pequeno e crescer."}, "profiles": ["imobiliaria_dono", "gestor"], "options": [{"pt": "Só eu"}, {"pt": "2 a 5"}, {"pt": "6 a 15"}, {"pt": "Mais de 15"}], "allow": ["unknown", "later"]},
  {"key": "filiais", "step": "operacao", "type": "select", "label": {"pt": "Quantas lojas, filiais ou equipes vocês têm?"}, "why": {"pt": "Cada região pode precisar de um conteúdo próprio."}, "profiles": ["imobiliaria_dono", "gestor"], "options": [{"pt": "Uma só"}, {"pt": "2 ou 3"}, {"pt": "4 ou mais"}], "allow": ["na", "unknown", "later"]},
  {"key": "equipe_propria", "step": "operacao", "type": "select", "label": {"pt": "Você trabalha sozinho(a) ou com equipe?"}, "why": {"pt": "Muda quanto do trabalho o Sales Boost precisa assumir por você."}, "profiles": ["corretor_autonomo", "corretor_associado"], "options": [{"pt": "Sozinho(a)"}, {"pt": "Com um(a) assistente"}, {"pt": "Com uma equipe pequena"}], "allow": ["later"]},
  {"key": "creci", "step": "operacao", "type": "text", "label": {"pt": "CRECI (pessoal ou da empresa)"}, "why": {"pt": "Exigência do setor: aparece na bio e nos anúncios."}, "allow": ["later"], "placeholder": {"pt": "Ex.: 12345-F ou 1234-J"}},
  {"key": "tempo_mercado", "step": "operacao", "type": "select", "label": {"pt": "Há quanto tempo no mercado imobiliário?"}, "why": {"pt": "Ajusta o tom: quem tem estrada tem histórias e clientes pra mostrar."}, "options": [{"pt": "Menos de 2 anos"}, {"pt": "2 a 5 anos"}, {"pt": "5 a 10 anos"}, {"pt": "Mais de 10 anos"}], "allow": ["later"]},
  {"key": "tipos_imovel", "step": "mercado", "type": "multi_select", "label": {"pt": "Quais imóveis são prioridade pra você?"}, "why": {"pt": "O formato do conteúdo muda: cobertura pede vídeo de vista, sala comercial pede números do ponto."}, "options": [{"pt": "Apartamentos"}, {"pt": "Casas"}, {"pt": "Coberturas"}, {"pt": "Terrenos"}, {"pt": "Salas e lojas comerciais"}, {"pt": "Imóveis na planta"}], "allow": ["unknown", "later"]},
  {"key": "padrao", "step": "mercado", "type": "multi_select", "label": {"pt": "Em que padrão você mais trabalha?"}, "why": {"pt": "Define a linguagem: luxo não fala como primeiro imóvel."}, "options": [{"pt": "Entrada / econômico"}, {"pt": "Médio padrão"}, {"pt": "Alto padrão"}, {"pt": "Luxo"}], "allow": ["unknown", "later"], "diagnostic": true},
  {"key": "faixa_preco", "step": "mercado", "type": "select", "label": {"pt": "Faixa de preço de venda mais comum"}, "why": {"pt": "Usamos só pra ajustar o tom e o público — nunca publicamos um preço que você não informou."}, "options": [{"pt": "Até R$500 mil", "en": "Up to R$500k"}, {"pt": "R$500 mil–R$1,5 mi", "en": "R$500k–R$1.5M"}, {"pt": "Acima de R$1,5 mi", "en": "Above R$1.5M"}], "show_if": {"key": "servicos", "any": ["Venda", "Lançamentos"]}, "allow": ["unknown", "later"], "needed_for": ["estrategia"]},
  {"key": "faixa_aluguel", "step": "mercado", "type": "select", "label": {"pt": "Faixa de aluguel mais comum"}, "why": {"pt": "Mesmo motivo: ajustar tom e público, sem inventar valor."}, "options": [{"pt": "Até R$ 2 mil"}, {"pt": "R$ 2 mil a R$ 5 mil"}, {"pt": "R$ 5 mil a R$ 10 mil"}, {"pt": "Acima de R$ 10 mil"}], "show_if": {"key": "servicos", "any": ["Locação"]}, "allow": ["unknown", "later"]},
  {"key": "carteira", "step": "mercado", "type": "select", "label": {"pt": "Quantos imóveis você tem na carteira hoje?"}, "why": {"pt": "Com poucos imóveis, o conteúdo de bairro e de autoridade pesa mais. Com muitos, o de imóvel."}, "options": [{"pt": "1–5"}, {"pt": "6–20"}, {"pt": "20+"}], "allow": ["unknown", "later"]},
  {"key": "cliente_tipico", "step": "mercado", "type": "select", "label": {"pt": "Hoje, quem mais compra ou aluga com você?"}, "why": {"pt": "Ponto de partida pro público. Se não souber, o Sales Boost ajuda a descobrir pelos dados."}, "options": [{"pt": "Família"}, {"pt": "Primeiro imóvel"}, {"pt": "Investidor"}, {"pt": "De fora do Rio"}, {"pt": "Aposentado"}], "allow": ["unknown", "later"]},
  {"key": "publico", "step": "mercado", "type": "multi_select", "label": {"pt": "E quem você quer atrair mais?"}, "why": {"pt": "Não precisa ser perfeito — a gente refina com o que os seus posts e conversas mostrarem."}, "options": [{"pt": "Famílias"}, {"pt": "Quem vai comprar o primeiro imóvel"}, {"pt": "Investidores"}, {"pt": "Compradores de alto padrão"}, {"pt": "Quem vem de fora do Rio"}, {"pt": "Locatários"}, {"pt": "Proprietários que querem vender ou alugar"}], "max": 3, "allow": ["unknown", "later"]},
  {"key": "diferenciais", "step": "mercado", "type": "text", "label": {"pt": "Por que os clientes escolhem você (ou os seus imóveis)?"}, "why": {"pt": "Vira argumento nos posts. Ex.: \"atendo em inglês\", \"especialista em Copacabana há 15 anos\"."}, "allow": ["unknown", "later"]},
  {"key": "concorrentes", "step": "mercado", "type": "multi_text", "label": {"pt": "Quem você vê como concorrente?"}, "why": {"pt": "Só comparamos dados públicos. Se não souber, o Sales Boost encontra quem aparece na sua região."}, "max": 5, "allow": ["unknown", "na", "later"], "placeholder": {"pt": "@ do Instagram ou nome"}},
  {"key": "prioridade_principal", "step": "prioridade", "type": "select", "label": {"pt": "Onde você quer melhorar primeiro?"}, "why": {"pt": "É isso que o Hermes coloca na frente quando monta a sua estratégia."}, "options": [{"pt": "Atrair mais compradores qualificados"}, {"pt": "Gerar mais conversas e pedidos de informação"}, {"pt": "Aumentar visitas aos imóveis"}, {"pt": "Captar novos imóveis para a carteira"}, {"pt": "Atrair proprietários que querem vender ou alugar"}, {"pt": "Divulgar imóveis prioritários"}, {"pt": "Fortalecer a marca"}, {"pt": "Melhorar o acompanhamento e a conversão de leads"}], "allow": ["unknown"], "diagnostic": true, "needed_for": ["estrategia"]},
  {"key": "prioridades_secundarias", "step": "prioridade", "type": "multi_select", "label": {"pt": "E depois disso? (até 3)"}, "why": {"pt": "Entram na estratégia com menos peso."}, "options": [{"pt": "Atrair mais compradores qualificados"}, {"pt": "Gerar mais conversas e pedidos de informação"}, {"pt": "Aumentar visitas aos imóveis"}, {"pt": "Captar novos imóveis para a carteira"}, {"pt": "Atrair proprietários que querem vender ou alugar"}, {"pt": "Divulgar imóveis prioritários"}, {"pt": "Fortalecer a marca"}, {"pt": "Melhorar o acompanhamento e a conversão de leads"}], "max": 3, "allow": ["na", "later"]},
  {"key": "canais_leads", "step": "canais", "type": "multi_select", "label": {"pt": "De onde vêm os seus clientes hoje?"}, "why": {"pt": "Mostra o que já funciona — e o que dá pra reforçar."}, "options": [{"pt": "Instagram"}, {"pt": "Portais (ZAP, VivaReal, OLX)"}, {"pt": "Indicação"}, {"pt": "Google"}, {"pt": "Site próprio"}, {"pt": "WhatsApp"}, {"pt": "Placa / fachada"}, {"pt": "Anúncios pagos"}], "allow": ["unknown", "later"]},
  {"key": "frequencia_posts", "step": "canais", "type": "select", "label": {"pt": "Com que frequência você posta no Instagram?"}, "why": {"pt": "Se o seu Instagram foi lido no diagnóstico, já deixamos uma sugestão pra você confirmar."}, "options": [{"pt": "Quase todo dia"}, {"pt": "3 a 5 vezes por semana"}, {"pt": "1 a 2 vezes por semana"}, {"pt": "Menos de 1 vez por semana"}, {"pt": "Quase nunca"}], "allow": ["unknown", "later"]},
  {"key": "tipo_conteudo", "step": "canais", "type": "multi_select", "label": {"pt": "O que você costuma postar?"}, "why": {"pt": "Pra não repetir o que já não deu certo e reforçar o que funciona."}, "options": [{"pt": "Fotos de imóveis"}, {"pt": "Vídeos / Reels de imóveis"}, {"pt": "Tour pelo imóvel"}, {"pt": "Conteúdo sobre o bairro"}, {"pt": "Dicas de compra e financiamento"}, {"pt": "Bastidores e marca pessoal"}, {"pt": "Quase não posto"}], "allow": ["later"]},
  {"key": "anuncios_pagos", "step": "canais", "type": "select", "label": {"pt": "Você faz anúncios pagos (Instagram/Facebook/Google)?"}, "why": {"pt": "Sem anúncio também dá: o Sales Boost começa pelo orgânico."}, "options": [{"pt": "Sim, todo mês"}, {"pt": "Às vezes"}, {"pt": "Não"}], "allow": ["later"]},
  {"key": "crm", "step": "canais", "type": "select", "label": {"pt": "Onde vocês anotam os interessados?"}, "why": {"pt": "Ajuda a saber se o lead se perde depois da primeira conversa."}, "options": [{"pt": "Em lugar nenhum / na memória"}, {"pt": "Planilha"}, {"pt": "CRM imobiliário"}, {"pt": "Outro sistema"}], "allow": ["unknown", "later"]},
  {"key": "leads_mes", "step": "canais", "type": "select", "label": {"pt": "Quantos interessados chegam por mês, mais ou menos?"}, "why": {"pt": "Não acompanha? Normal — marque \"Não sei\". O Sales Boost passa a medir pra você."}, "options": [{"pt": "Menos de 10"}, {"pt": "10 a 30"}, {"pt": "30 a 100"}, {"pt": "Mais de 100"}], "allow": ["unknown", "later"]},
  {"key": "atendimento", "step": "canais", "type": "select", "label": {"pt": "Quem responde quem chega pelo Instagram ou WhatsApp?"}, "why": {"pt": "Define pra quem o Sales Boost entrega a conversa pronta."}, "options": [{"pt": "Eu mesmo(a)"}, {"pt": "Os corretores"}, {"pt": "Uma recepção / SDR"}, {"pt": "Ninguém fixo"}], "allow": ["unknown", "later"]},
  {"key": "tempo_resposta", "step": "canais", "type": "select", "label": {"pt": "Em quanto tempo vocês costumam responder?"}, "why": {"pt": "No imóvel, quem responde primeiro costuma levar a visita."}, "options": [{"pt": "Em minutos"}, {"pt": "No mesmo dia"}, {"pt": "No dia seguinte ou depois"}], "allow": ["unknown", "later"]},
  {"key": "metricas", "step": "canais", "type": "multi_select", "label": {"pt": "O que vocês acompanham hoje?"}, "why": {"pt": "Só pra saber de onde partimos — não precisa ter número nenhum."}, "options": [{"pt": "Número de interessados"}, {"pt": "Visitas agendadas"}, {"pt": "Propostas"}, {"pt": "Vendas / locações fechadas"}, {"pt": "Origem dos clientes"}, {"pt": "Nada ainda"}], "allow": ["unknown", "later"]}
 ],
 "derive": [
  {"to": "transacao", "from": "servicos", "rules": [{"all": ["Venda", "Locação"], "value": "Os dois"}, {"any": ["Locação", "Aluguel por temporada"], "value": "Aluguel"}, {"any": ["Venda", "Lançamentos"], "value": "Venda"}]}
 ],
 "priority_actions": {
  "Atrair mais compradores qualificados": "Posts de imóvel com bairro, faixa e chamada de visita, mais Reels de tour e \"3 coisas perto\" pra atrair quem já está procurando.",
  "Gerar mais conversas e pedidos de informação": "Chamadas claras em todo post (\"Comente VISITA\", caixa de perguntas) e resposta automática com a sua aprovação.",
  "Aumentar visitas aos imóveis": "Conteúdo que termina em convite de visita e o \"Comente QUERO\" que leva a conversa até o agendamento.",
  "Captar novos imóveis para a carteira": "Conteúdo pra proprietários: como avaliar o imóvel, o que valoriza no bairro e por que anunciar com você.",
  "Atrair proprietários que querem vender ou alugar": "Posts de mercado local e bastidores de venda que mostram a sua autoridade pra quem tem imóvel.",
  "Divulgar imóveis prioritários": "Pacote completo por imóvel (carrossel, Reels, stories) priorizando os imóveis que você marcar.",
  "Fortalecer a marca": "Marca pessoal e prova social: bastidores, entregas de chave e conteúdo do bairro com a sua cara.",
  "Melhorar o acompanhamento e a conversão de leads": "Cada conversa vira registro e lembrete de retorno — ninguém fica sem resposta."
 },
 "audience_hypotheses": [
  {"when": {"key": "padrao", "any": ["Alto padrão", "Luxo"]}, "text": "Compradores de alto padrão costumam pesquisar o estilo de vida do bairro antes do imóvel — conteúdo de vizinhança tende a atrair esse público."},
  {"when": {"key": "padrao", "any": ["Entrada / econômico"]}, "text": "Quem compra o primeiro imóvel costuma ter dúvidas de financiamento — conteúdo que ensina tende a puxar conversa."},
  {"when": {"key": "servicos", "any": ["Locação"]}, "text": "Locatários decidem rápido: anúncio com o valor total do mês e visita fácil tende a gerar mais contato."},
  {"when": {"key": "servicos", "any": ["Lançamentos"]}, "text": "Lançamento costuma atrair investidores — vale testar conteúdo de planta, prazo de obra e região."},
  {"when": {"key": "prioridade_principal", "any": ["Captar novos imóveis para a carteira", "Atrair proprietários que querem vender ou alugar"]}, "text": "Proprietários do seu bairro que pensam em vender podem responder a conteúdo de mercado local e de avaliação."}
 ],
 "diagnosis_readiness": {
  "cta_example": "Comente VISITA",
  "region_label": "bairro ou região",
  "cta_pattern": "(comente|coment[aá]rio|chama|chame|me chama|direct|\\bdm\\b|whats|wa\\.me|link na bio|agend|visita|fale comigo|me manda|mande)",
  "question_pattern": "(\\?|quanto|valor|pre[cç]o|dispon[ií]vel|onde fica|qual (o )?bairro|financ|ainda tem|aceita)",
  "bio_checks": [{"key": "creci", "label": "CRECI na bio", "short": "CRECI", "pattern": "creci", "why": "Exigência do setor e sinal de confiança pra quem chega."}, {"key": "contato", "label": "WhatsApp ou telefone na bio", "short": "WhatsApp ou telefone", "pattern": "(whats|wa\\.me|zap|\\(?\\d{2}\\)?\\s?9\\d{4}[- ]?\\d{4})", "why": "Sem um jeito direto de falar com você, o interessado desiste."}, {"key": "regiao", "label": "Bairro ou região na bio", "short": "bairro ou região", "use_answers": "bairros", "pattern": "(rio|zona sul|zona norte|zona oeste|barra|recreio|copacabana|ipanema|leblon|botafogo|tijuca|flamengo|niter[oó]i|lagoa|gávea|gavea|laranjeiras)", "why": "Quem procura imóvel procura por bairro."}],
  "region_terms": ["Copacabana", "Ipanema", "Leblon", "Botafogo", "Flamengo", "Laranjeiras", "Lagoa", "Gávea", "Jardim Botânico", "Humaitá", "Urca", "Leme", "Tijuca", "Grajaú", "Vila Isabel", "Méier", "Barra", "Recreio", "Jacarepaguá", "Freguesia", "Centro", "Zona Sul", "Zona Norte", "Zona Oeste", "Niterói", "Icaraí"]
 }
}$v2$::jsonb)
where key = 'imoveis_rio';
